    use super::dedup_case_insensitive;

    #[test]
    fn preserves_first_spelling() {
        assert_eq!(
            dedup_case_insensitive(&["  Foo", "foo", "BAR", "bar ", "Baz"]),
            vec!["Foo".to_string(), "BAR".to_string(), "Baz".to_string()]
        );
    }

    #[test]
    fn skips_empty_values() {
        assert_eq!(
            dedup_case_insensitive(&["", "   ", " Quux "]),
            vec!["Quux".to_string()]
        );
    }
